import React from 'react';
import {
	FormControl,
	Heading,
	Table,
	Tbody,
	Th,
	Thead,
	Tr,
	VStack,
	useDisclosure,
	FormLabel,
	Link,
} from '@chakra-ui/react';

import { calendarThemeSettingInputs } from '../../../lib';
import { ColorInputRow } from './ColorInputRow';
import { HeadingRow } from './HeadingRow';
import { CategoryColorSettings } from './CategoryColorSettings';
import { BaseModal } from '../../ui';
import { RadiusSettings } from './radius-settings';

import type { ICalendarPlusSettings, CategoryColorChangeHandler, ChangeHandler } from '../../../lib';

interface IThemeSettingsProps {
	categories: string[];
	settings: ICalendarPlusSettings | null;
	handleInputChange: ChangeHandler;
	handleCheckboxChange: ChangeHandler;
	handleColorInputChange: ChangeHandler;
	handleCategoryColor: CategoryColorChangeHandler;
	updateSettings: (updates: Partial<ICalendarPlusSettings>) => void;
}

export const ThemeSettings: React.FunctionComponent<IThemeSettingsProps> = ({
	categories,
	settings,
	handleColorInputChange,
	handleCategoryColor,
	updateSettings,
}) => {
	const {
		isOpen: isRadiusSettingsOpened,
		onClose: onCloseRadiusSettings,
		onToggle: onRadiusSettingsOpen,
	} = useDisclosure();
	return (
		<>
			<Heading mb={4}>Colors &amp; Styles</Heading>
			<VStack spacing={8}>
				<FormControl>
					<Table variant='simple' width='min'>
						<Thead>
							<Tr>
								<Th minWidth={96} borderBottom='none'></Th>
								<Th minWidth={48} textAlign='center' borderBottom='none'>
									Light Mode Color
								</Th>
								<Th minWidth={48} textAlign='center' borderBottom='none'>
									Dark Mode Color
								</Th>
							</Tr>
						</Thead>
						<Tbody>
							{calendarThemeSettingInputs.map((item) =>
								item.type === 'heading' ? (
									<HeadingRow key={item.label} label={item.label} />
								) : (
									<ColorInputRow
										key={item.id}
										id={item.id}
										label={item.label}
										defaultColor={item.defaultColor}
										settings={settings}
										handleColorInputChange={handleColorInputChange}
									/>
								)
							)}
						</Tbody>
					</Table>
				</FormControl>
				<CategoryColorSettings
					categories={categories}
					settings={settings}
					handleCategoryColor={handleCategoryColor}
				/>
				<FormControl>
					<Link href='#' onClick={onRadiusSettingsOpen}>
						<FormLabel whiteSpace='pre' cursor='pointer'>
							Edit Calendar Radius Settings
						</FormLabel>
					</Link>
				</FormControl>
				<BaseModal isOpen={isRadiusSettingsOpened} onClose={onCloseRadiusSettings} header='Radius Settings'>
					<RadiusSettings settings={settings} updateSettings={updateSettings} />
				</BaseModal>
			</VStack>
		</>
	);
};
