import React from 'react';
import { Input, Td, Tr } from '@chakra-ui/react';

import type { ChangeHandler, ICalendarPlusSettings } from '../../../lib';

interface IColorInputRowProps {
	id: string;
	label: string;
	defaultColor: string;
	settings: ICalendarPlusSettings | null;
	handleColorInputChange: ChangeHandler;
}

export const ColorInputRow: React.FC<IColorInputRowProps> = ({
	id,
	label,
	defaultColor,
	settings,
	handleColorInputChange,
}) => (
	<Tr key={id}>
		<Td>{label}</Td>
		<Td textAlign='center'>
			<Input
				id={`${id}-light`}
				type='color'
				value={settings?.styles?.light[id] || defaultColor}
				onChange={handleColorInputChange}
				cursor='pointer'
				size='sm'
				width='100%'
			/>
		</Td>
		<Td textAlign='center'>
			<Input
				id={`${id}-dark`}
				type='color'
				value={settings?.styles?.dark[id] || defaultColor}
				onChange={handleColorInputChange}
				cursor='pointer'
				size='sm'
				width='100%'
			/>
		</Td>
	</Tr>
);
